// ============================================================
// HECATECH MAIN ORCHESTRATOR — Data Transform
// Reads both sheets, builds full package for sub-workflows
// ============================================================

const baoCaoItems = $('Read Bao Cao Sheet').all();
const tongHopItems = $input.all(); // Tổng hợp is last node output

// --- Helpers ---
const col = (row, idx) => { const keys = Object.keys(row.json||row); return (row.json||row)[keys[idx]]; };
const fmt = (n) => {
  n = parseFloat(n) || 0;
  if (Math.abs(n) >= 1e9) return (n/1e9).toFixed(2) + ' tỷ';
  if (Math.abs(n) >= 1e6) return Math.round(n/1e6) + ' tr';
  return Math.round(n).toLocaleString('vi-VN');
};

// --- Extract Báo cáo ---
const headerRow = baoCaoItems[0]?.json || {};
const rawDate = col({ json: headerRow }, 0);
const reportDate = rawDate
  ? new Date(rawDate).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' })
  : new Date().toLocaleDateString('vi-VN');

const projects = [];
for (let i = 1; i < baoCaoItems.length; i++) {
  const r = baoCaoItems[i].json;
  const name = (col({ json: r }, 0) || '').toString().trim();
  if (!name || name === 'NaN' || name.length < 2) continue;
  const doanhSo  = parseFloat(col({ json: r }, 1)) || 0;
  const doanhThu = parseFloat(col({ json: r }, 2)) || 0;
  const chiPhi   = parseFloat(col({ json: r }, 4)) || 0;
  const loiNhuan = parseFloat(col({ json: r }, 5)) || 0;
  const redThr   = parseFloat(col({ json: r }, 6)) || 0;
  const greenThr = parseFloat(col({ json: r }, 7)) || 0;
  const status   = (col({ json: r }, 8) || '🔴').toString().trim();
  projects.push({
    name, status,
    doanhSo: fmt(doanhSo), doanhThu: fmt(doanhThu),
    chiPhi: fmt(chiPhi),   loiNhuan: fmt(loiNhuan),
    loiNhuan_raw: loiNhuan, doanhSo_raw: doanhSo,
    margin: doanhThu > 0 ? (loiNhuan/doanhThu*100).toFixed(1)+'%' : 'N/A',
    cpds:   doanhSo  > 0 ? (chiPhi/doanhSo*100).toFixed(1)+'%'   : 'N/A',
    target: fmt(redThr) + ' → ' + fmt(greenThr)
  });
}

// --- Extract Tổng hợp MTD ---
const metrics = {};
const today = new Date();
const yesterdayColIdx = 5 + today.getDate() - 1;
tongHopItems.forEach(item => {
  const name = (col(item, 0) || '').toString().trim();
  if (name && name !== 'NaN') {
    metrics[name] = {
      mtd: parseFloat(col(item, 5)) || 0,
      yesterday: parseFloat(col(item, yesterdayColIdx)) || 0
    };
  }
});

// --- Build dashboard summary ---
const red    = projects.filter(p => p.status === '🔴');
const yellow = projects.filter(p => p.status === '🟡');
const green  = projects.filter(p => p.status === '✅');
const totalDS = projects.reduce((s, p) => s + p.doanhSo_raw, 0);
const totalLN = projects.reduce((s, p) => s + p.loiNhuan_raw, 0);

const dashboardData = {
  reportDate,
  summary: {
    green: green.length, yellow: yellow.length, red: red.length,
    totalDoanhSo: fmt(totalDS), totalLoiNhuan: fmt(totalLN),
    overallMargin: totalDS > 0 ? (totalLN/totalDS*100).toFixed(1)+'%' : '0%'
  },
  tiktokMTD: {
    gmv:             fmt(metrics['Tổng GMV']?.mtd || 0),
    loiNhuanRong:    fmt(metrics['★ LỢI NHUẬN RÒNG']?.mtd || 0),
    netProfitMargin: ((metrics['Net Profit Margin']?.mtd || 0)*100).toFixed(1)+'%'
  },
  projects,
  redProjects:    red.map(p => p.name),
  yellowProjects: yellow.map(p => p.name),
  greenProjects:  green.map(p => p.name)
};

// --- Project configs (sheet names + Lark webhooks) ---
// Sub-workflows will read these to know where to send warnings
const projectConfigs = [
  { id: 'XKMVN', name: 'Xịt Khử Mùi VN',  sheet: 'XKMVN', webhook: $vars.LARK_XKMVN_WEBHOOK, market: 'VN' },
  { id: 'KTLVN', name: 'KTL Vietnam',       sheet: 'KTLVN', webhook: $vars.LARK_KTLVN_WEBHOOK, market: 'VN' },
  { id: 'TDCVN', name: 'TDC Vietnam',       sheet: 'TDCVN', webhook: $vars.LARK_TDCVN_WEBHOOK, market: 'VN' },
  { id: 'KTMVN', name: 'KTM Vietnam',       sheet: 'KTMVN', webhook: $vars.LARK_KTMVN_WEBHOOK, market: 'VN' },
  { id: 'MNVN',  name: 'MN Vietnam',        sheet: 'MNVN',  webhook: $vars.LARK_MNVN_WEBHOOK,  market: 'VN' },
  { id: 'KTMR',  name: 'KTM Market',        sheet: 'KTMR',  webhook: $vars.LARK_KTMR_WEBHOOK,  market: 'Multi' },
  { id: 'SRMR',  name: 'SR Market',         sheet: 'SRMR',  webhook: $vars.LARK_SRMR_WEBHOOK,  market: 'Multi' },
  { id: 'KTLTL', name: 'KTL Thailand',      sheet: 'KTLTL', webhook: $vars.LARK_KTLTL_WEBHOOK, market: 'TH' },
  { id: 'XKMTL', name: 'XKM Thailand',      sheet: 'XKMTL', webhook: $vars.LARK_XKMTL_WEBHOOK, market: 'TH' },
  { id: 'XKMPH', name: 'XKM Philippines',   sheet: 'XKMPH', webhook: $vars.LARK_XKMPH_WEBHOOK, market: 'PH' },
  { id: 'XKMMY', name: 'XKM Malaysia',      sheet: 'XKMMY', webhook: $vars.LARK_XKMMY_WEBHOOK, market: 'MY' }
];

// --- Day flags (weekly agents only run on Monday) ---
const isMonday = today.getDay() === 1; // 0=Sun, 1=Mon

// Return single item with full package — flows into sub-workflows
return [{ json: { dashboardData, projectConfigs, isMonday } }];
